style.css:
@-moz-document domain("amazon.com"), url-prefix("https://www.amazon.com/") {
/* Anchor the side gutters to the viewport, outside Amazon's centered deck. */
html:root {
  isolation: isolate !important;
  color-scheme: dark !important;
}
html:root::before {
  content: "" !important;
  position: fixed !important;
  inset: 0 !important;
  z-index: -1 !important;
  pointer-events: none !important;
}
html:root body, html:root body #a-page,
html:root[data-darkreader-mode] body,
html:root[data-darkreader-mode] body #a-page {
  background: transparent !important;
}
/* Use the same viewport origin for the gutters and storefront deck. */
html:root, html:root::before, html body #a-page #gwm-Deck {
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* Shared colors and type from ChatGPT Hacker Green v1.5.6. */
html {
  --ahg-font: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace;
  --ahg-text: #d9ffe6;
  --ahg-muted: #9ee5b6;
  --ahg-link: #7fffac;
  --ahg-edge: rgba(28,240,102,.36);
  --ahg-faint-edge: rgba(32,243,107,.18);
  --ahg-panel: rgba(2,26,12,.82);
  --ahg-control: rgba(4,43,20,.95);
  --ahg-menu: rgba(1,23,10,.96);
  --ahg-hover: rgba(12,91,39,.56);
  --ahg-focus: #00ff66;
  --ahg-action: #00e85c;
  --ahg-action-hover: #38ff87;
  --ahg-action-text: #001b09;
}
#pageContent, #gw-layout, #desktop-grid,
#mobile-grid, #gw-card-layout, #search, #dp, #dp-container,
#ppd, #sc-retail-cart-container, #sc-retail-cart-container .sc-list-body,
#orderFilter, #ordersContainer, #yourOrders, #ya-page,
#checkout, #checkoutContent, .a-container,
.a-page-normal, .a-page-section, .a-color-base-background {
  background-color: transparent !important;
}
/* Amazon paints the side gutters with the deck's 100vw spread shadow. */
html:root body #a-page #gwm-Deck {
  box-shadow: none !important;
}

/* Amazon's Gateway deck has separate above- and below-fold wrappers.
   Clear only those structural surfaces so the deck grid stays visible. */
html body #a-page #gwm-Deck-cf,
html body #a-page #gwm-Deck-atf,
html body #a-page #gwm-Deck-btf,
html body #a-page #gwm-window-layout,
html body #a-page #gwm-window-container-wrapper,
html body #a-page #gwm-window-container,
html body #a-page #gwm-window,
html body #a-page .gwm-window-tile {
  background-color: transparent !important;
  background-image: none !important;
}
/* Clear storefront layout fills and scrims above the fixed grid.
   Scope these to canvas wrappers so cards and media keep their own surfaces. */
#a-page #pageContent, #a-page #gw-layout, #a-page #desktop-grid,
#a-page #gw-content, #a-page #gw-desktop,
#a-page #mobile-grid, #a-page #gw-card-layout, #a-page #gw-content-grid,
#a-page #gw-desktop-grid, #a-page #gw-mobile-grid,
#a-page .gw-layout, #a-page .gw-card-layout, #a-page .gw-card-layout-row,
#a-page .gw-content-grid, #a-page .gw-content-grid-row,
#a-page #gw-layout::before, #a-page #gw-layout::after,
#a-page #gw-card-layout::before, #a-page #gw-card-layout::after,
#a-page #desktop-grid::before, #a-page #desktop-grid::after {
  background-color: transparent !important;
  background-image: none !important;
}
html body, #a-page, #navbar, #navFooter, #hmenu-canvas, .nav-flyout,
.a-popover-wrapper, .a-modal-scroller, .a-tooltip, .a-dropdown,
input, button, select, textarea, #navbar input, #navbar select {
  font-family: var(--ahg-font) !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
  color: var(--ahg-text) !important;
}
h1, h2, h3, h4, h5, h6, .a-color-base, .a-color-price, .a-price,
.a-price .a-offscreen, .a-price .a-price-whole, .a-price .a-price-fraction,
.a-alert-heading, .a-size-base-plus, .a-text-bold,
#productTitle, #title, #nav-cart-count, .a-color-success {
  color: var(--ahg-text) !important;
}
.a-color-secondary, .a-color-tertiary, .a-color-state,
.a-color-alternate-background, .a-text-strike, .a-text-strikethrough,
#nav-main .nav-a, #navFooter .navFooterDescText {
  color: var(--ahg-muted) !important;
}
a, .a-link-normal, .a-link-emphasis, a:visited, #navFooter a,
#nav-subnav .nav-a, #navbar .nav-a, #hmenu-canvas a {
  color: var(--ahg-link) !important;
}
a:hover, .a-link-normal:hover, .a-link-emphasis:hover,
#navFooter a:hover, #nav-subnav .nav-a:hover, #navbar .nav-a:hover,
#hmenu-canvas a:hover, a:hover .a-color-base {
  color: #b5ffd1 !important;
}
.a-color-error, .a-color-attainable {
  color: #f0fff5 !important;
  text-decoration: underline;
}
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }

/* Navigation, search, and footer. Leave Amazon's sprites intact. */
#navbar, #nav-belt, #nav-main, #nav-progressive-subnav, #nav-subnav,
#navFooter, #navFooter .navFooterBackToTop, #navFooter .navFooterCopyright,
#navFooter .navFooterDescLine, #navFooter .navFooterLine {
  background-color: rgba(1,20,9,.58) !important;
  border-color: var(--ahg-faint-edge) !important;
}
#navbar, #navFooter { background-color: var(--ahg-panel) !important; }
#nav-logo .nav-logo-base, #nav-logo .nav-logo-locale,
#nav-logo .nav-logo-sprites, .a-icon-logo {
  filter: drop-shadow(0 0 7px rgba(0,255,102,.76)) !important;
}
#navbar .nav-line-1, #navbar .nav-line-2, #navbar .nav-text,
#navFooter .navFooterBackToTopText, #navFooter .navFooterColHead,
#navFooter .navFooterDescItem, #navFooter .icp-color-base {
  color: var(--ahg-text) !important;
}
#nav-main .nav-a:hover, #navbar .nav-a:hover,
#nav-logo a:hover, #nav-cart:hover, #nav-tools .nav-a:hover,
#navFooter .navFooterBackToTop:hover {
  background-color: var(--ahg-hover) !important;
  border-color: var(--ahg-edge) !important;
}
#nav-search .nav-search-field, #nav-search .nav-search-scope,
#nav-search .nav-fill, #nav-search .nav-left .nav-search-facade,
#nav-search .nav-search-label, #twotabsearchtextbox, #nav-search-keywords {
  background-color: var(--ahg-control) !important;
  color: var(--ahg-text) !important;
  border-color: var(--ahg-edge) !important;
}
#nav-search .nav-search-submit, #nav-search-submit-button {
  background-color: var(--ahg-action) !important;
  color: var(--ahg-action-text) !important;
}
#nav-search .nav-search-submit:hover, #nav-search-submit-button:hover {
  background-color: var(--ahg-action-hover) !important;
}
#nav-search .nav-searchbar:focus-within {
  box-shadow: 0 0 0 2px var(--ahg-focus) !important;
}

/* Storefront cards, search tiles, cart rows, and product information. */
.a-box, .a-cardui, .a-carousel-card, .a-section.a-spacing-base.s-card-container,
.s-card-container, .s-border, .s-product-image-container,
#buybox .a-box, #desktop_buybox .a-box, #mobile_buybox .a-box,
#aplus, #productOverview_feature_div, #prodDetails,
#customerReviews, #reviewsMedley, #reviews-filter-info,
#sc-active-cart, #sc-saved-cart, .sc-list-item,
.order-card, .order-info, .a-accordion .a-accordion-row-container,
.a-alert, .a-box-group, #nav-flyout-ya-newCust,
#desktop-grid .a-cardui, #mobile-grid .a-cardui,
[data-csa-c-type="widget"] > .a-cardui {
  background-color: var(--ahg-panel) !important;
  border-color: var(--ahg-edge) !important;
  color: var(--ahg-text) !important;
}
.a-cardui, .s-card-container, #buybox .a-box, #desktop_buybox .a-box,
.order-card, #sc-active-cart, #sc-saved-cart {
  border-radius: 12px !important;
  box-shadow: inset 0 0 0 1px var(--ahg-faint-edge) !important;
}
.a-cardui:hover, .s-card-container:hover, .order-card:hover,
.a-cardui:focus-within, .s-card-container:focus-within {
  box-shadow: inset 0 0 0 1px var(--ahg-edge), 0 0 10px rgba(0,255,102,.09) !important;
}
.a-box > .a-box-inner, .a-alert .a-alert-container,
.a-cardui .a-cardui-body, .a-cardui .a-cardui-header,
.a-cardui .a-cardui-footer, .a-accordion .a-accordion-inner,
.s-card-container .a-section, .s-card-container .s-image-square-aspect,
.s-card-container .s-image-tall-aspect, .a-carousel .a-carousel-viewport,
#sc-active-cart .sc-list-body, #nav-subnav .nav-a,
#navFooter .navFooterLinkCol, #wayfinding-breadcrumbs_feature_div {
  background-color: transparent !important;
  border-color: var(--ahg-faint-edge) !important;
}
.s-product-image-container { background-color: transparent !important; }
.a-button-thumbnail, .a-button-thumbnail .a-button-inner {
  background-color: transparent !important;
}
.a-button-thumbnail:hover, .a-button-thumbnail.a-button-selected {
  box-shadow: 0 0 0 1px var(--ahg-focus) !important;
}
#s-refinements, #leftNav, #departments, #filters, .s-refinements,
html body #search .sg-col.sg-col-4-of-12.s-matching-dir > .sg-col-inner {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg, rgba(13,92,47,.35) 0%,
    rgba(4,47,25,.28) 40%, rgba(1,19,11,.59) 100%) !important;
  border-color: var(--ahg-edge) !important;
  border-radius: 12px !important;
}
/* Keep the glass on the full filter column and clear the nested fills. */
html body #search .sg-col.sg-col-4-of-12.s-matching-dir,
html body #search .sg-col.sg-col-4-of-12.s-matching-dir > .sg-col-inner > .a-section,
html body #search .sg-col.sg-col-4-of-12.s-matching-dir .s-widget-container[class~="widgetId=refinements"],
html body #search .sg-col.sg-col-4-of-12.s-matching-dir #s-refinements {
  background-color: transparent !important;
  background-image: none !important;
}
html body #search .sg-col.sg-col-4-of-12.s-matching-dir > .sg-col-inner {
  box-shadow: inset 0 0 0 1px var(--ahg-edge) !important;
}
#s-refinements .s-navigation-item:hover, #leftNav li:hover {
  background-color: rgba(17,117,53,.40) !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}
.a-badge .a-badge-text, .a-badge .a-badge-label,
.s-pagination-item, .a-pagination li a, .a-tabs li a,
.a-label, .a-expander-header, .a-accordion-row,
.a-price-badge .a-badge-text {
  background-color: var(--ahg-control) !important;
  border-color: var(--ahg-edge) !important;
  color: var(--ahg-text) !important;
}
.s-pagination-item:hover, .s-pagination-selected,
.a-pagination li a:hover, .a-pagination .a-selected a,
.a-tabs .a-active a, .a-accordion-active .a-accordion-row {
  background-color: rgba(12,103,43,.72) !important;
  border-color: var(--ahg-focus) !important;
  color: #f0fff5 !important;
}
.a-divider.a-divider-break::after, .a-divider.a-divider-section .a-divider-inner,
.a-divider.a-divider-normal .a-divider-inner {
  background-image: none !important;
  border-color: var(--ahg-faint-edge) !important;
}
.a-divider.a-divider-break h5 { background-color: var(--ahg-panel) !important; }
hr, .a-bordered, .a-border-top, .a-border-bottom,
.a-table-striped td, .a-keyvalue td, .a-keyvalue th,
.a-vertical-stripes td, .navFooterLine {
  border-color: var(--ahg-faint-edge) !important;
}
table.a-bordered td, table.a-bordered th, table.a-keyvalue td,
table.a-keyvalue th, .a-table-striped tr:nth-child(even) td,
.a-vertical-stripes tr:nth-child(odd) td, #productDetails_techSpec_section_1 th,
#productDetails_detailBullets_sections1 th {
  background-color: var(--ahg-panel) !important;
  border-color: var(--ahg-faint-edge) !important;
  color: var(--ahg-text) !important;
}

/* Menus and dialogs use the higher-opacity reference surface. */
#hmenu-canvas, #hmenu-content, #hmenu-customer-profile,
.nav-flyout, .nav-flyout .nav-template,
#nav-flyout-searchAjax, .s-suggestion-container,
.a-popover-wrapper, .a-popover-header, .a-popover-inner,
.a-dropdown-item, .a-dropdown-link, .a-tooltip .a-tooltip-inner,
[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"] {
  background-color: var(--ahg-menu) !important;
  border-color: rgba(34,255,112,.41) !important;
  color: #d9ffe5 !important;
}
.nav-flyout, #hmenu-canvas, .a-popover-wrapper,
.a-tooltip .a-tooltip-inner, [role="dialog"], [role="alertdialog"] {
  box-shadow: 0 12px 35px rgba(0,0,0,.62), 0 0 18px rgba(0,180,67,.14) !important;
}
#hmenu-content .hmenu-item:hover, .nav-flyout .nav-link:hover,
.nav-flyout a:hover, .s-suggestion-container:hover,
.a-dropdown-link:hover, .a-dropdown-item.a-active .a-dropdown-link,
[role="menuitem"]:hover, [role="option"]:hover,
[role="option"][aria-selected="true"] {
  background-color: rgba(12,103,43,.72) !important;
  color: #f0fff5 !important;
}
.nav-flyout .nav-arrow .nav-arrow-inner { border-bottom-color: var(--ahg-menu) !important; }

/* Form controls and button variants retain their native dimensions. */
input[type="text"], input[type="search"], input[type="email"],
input[type="password"], input[type="tel"], input[type="number"],
input[type="url"], textarea, select, select option,
.a-input-text, .a-input-text-wrapper input, .a-native-dropdown {
  background-color: var(--ahg-control) !important;
  border-color: var(--ahg-edge) !important;
  color: var(--ahg-text) !important;
}
input::placeholder, textarea::placeholder { color: var(--ahg-muted) !important; }
input[type="checkbox"], input[type="radio"] { accent-color: #00e85c !important; }
.a-button, .a-button .a-button-inner, button.a-button-text {
  background-color: var(--ahg-control) !important;
  background-image: none !important;
  border-color: var(--ahg-edge) !important;
  box-shadow: none !important;
}
.a-button .a-button-text, .a-dropdown-prompt {
  color: var(--ahg-text) !important;
  font-family: var(--ahg-font) !important;
}
.a-button:hover, .a-button:hover .a-button-inner {
  background-color: var(--ahg-hover) !important;
  border-color: var(--ahg-focus) !important;
}
.a-button-primary, .a-button-primary .a-button-inner,
.a-button-primary:hover, .a-button-primary:hover .a-button-inner {
  background-color: var(--ahg-action) !important;
  border-color: var(--ahg-action) !important;
}
.a-button-primary:hover .a-button-inner { background-color: var(--ahg-action-hover) !important; }
.a-button-primary .a-button-text, .a-button-primary .a-button-input {
  color: var(--ahg-action-text) !important;
}
.a-button-disabled, button:disabled, input:disabled, select:disabled {
  opacity: .55 !important;
}
a:focus-visible, button:focus-visible, input:focus-visible,
textarea:focus-visible, select:focus-visible, [tabindex]:focus-visible,
.a-button:focus-within {
  outline: 2px solid var(--ahg-focus) !important;
  outline-offset: 2px !important;
}

/* Keep product photos and branded image assets in their original colors. */
.a-button-thumbnail .a-button-inner, .a-button-thumbnail:hover .a-button-inner {
  background-color: transparent !important;
}

/* Everywhere Cart: a single glass surface behind the compact cart. */
html body #ewc-content.ewc-compact {
  background: linear-gradient(145deg, rgba(6,46,22,.84), rgba(2,26,12,.82)) !important;
  color: var(--ahg-text) !important;
  box-shadow: inset 1px 0 0 var(--ahg-edge), -6px 0 24px rgba(0,225,88,.13) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
html body #ewc-content.ewc-compact .ewc-compact-head,
html body #ewc-content.ewc-compact .ewc-compact-view-cart-header,
html body #ewc-content.ewc-compact .ewc-cart-header,
html body #ewc-content.ewc-compact .ewc-subtotal,
html body #ewc-content.ewc-compact #ewc-compact-actions-container,
html body #ewc-content.ewc-compact .ewc-compact-actions,
html body #ewc-content.ewc-compact #ewc-compact-body,
html body #ewc-content.ewc-compact .ewc-scroller,
html body #ewc-content.ewc-compact .ewc-active-cart {
  background: transparent !important;
}
#ewc-content.ewc-compact .ewc-subtotal-label .a-color-base {
  color: var(--ahg-muted) !important;
}
#ewc-content.ewc-compact .ewc-subtotal-amount .a-color-price {
  color: var(--ahg-link) !important;
}
#ewc-content.ewc-compact .ewc-item-separator {
  background: var(--ahg-faint-edge) !important;
  border-color: var(--ahg-faint-edge) !important;
}
#ewc-content.ewc-compact .ewc-go-to-cart .a-button {
  background: var(--ahg-control) !important;
  border-color: var(--ahg-edge) !important;
}
#ewc-content.ewc-compact .ewc-go-to-cart .a-button-inner {
  background: transparent !important;
}
#ewc-content.ewc-compact .ewc-go-to-cart .a-button-text {
  color: var(--ahg-text) !important;
}
#ewc-content.ewc-compact .ewc-go-to-cart .a-button:hover {
  background: rgba(12,103,43,.72) !important;
  border-color: var(--ahg-focus) !important;
  box-shadow: 0 0 10px rgba(0,255,102,.16) !important;
}

/* Inner surfaces behind content and product photos. */
html body #a-page #gwm-Deck .gwm-Card,
html body #a-page #gwm-Deck .gwm-SubCard,
html body #a-page #gwm-Deck .gwm-tile,
html body #a-page #gwm-Deck [class*="_npack-asin-card_style_tile-wrapper__"],
html body #a-page #gwm-Deck [class*="_npack-asin-card_style_theming-background-override__"],
html body #a-page #search .s-card-container .s-product-image-container,
html body #a-page #search .s-card-container .s-image-square-aspect,
html body #a-page #search .s-card-container .s-image-tall-aspect,
html body #a-page .a-cardui .a-carousel-card,
html body #ewc-content.ewc-compact .ewc-active-cart .ewc-item {
  background-color: rgba(6,46,22,.62) !important;
  border-color: var(--ahg-faint-edge) !important;
}
/* Let the tile glass show through its nested image wrappers. */
html body #a-page #gwm-Deck [class*="_npack-asin-card_style_asin-image-container__"],
html body #a-page #gwm-Deck [class*="_npack-asin-card_style_tile-container__"],
html body #a-page .a-box > .a-box-inner.a-color-alternate-background,
html body #a-page .a-cardui .a-cardui-body.a-color-alternate-background {
  background-color: transparent !important;
}
html body #a-page #gwm-Deck .gwm-navigation-left-button,
html body #a-page #gwm-Deck .gwm-navigation-right-button {
  background-color: var(--ahg-control) !important;
  border-color: var(--ahg-edge) !important;
}

/* Desktop search results column and nested product surfaces. */
html body #search .s-desktop-content > .sg-col.sg-col-8-of-12.s-matching-dir > .sg-col-inner {
  background: linear-gradient(145deg, rgba(13,92,47,.35), rgba(1,19,11,.59)) rgba(2,24,13,.43) !important;
  border-radius: 12px !important;
  box-shadow: inset 0 0 0 1px var(--ahg-edge) !important;
}
html body #search .s-desktop-content,
html body #search .s-desktop-content > .sg-col.sg-col-8-of-12.s-matching-dir,
html body #search .s-main-slot.s-search-results,
html body #search .s-main-slot .s-card-container .desktop-grid-content-view {
  background: transparent !important;
}
html body #search .s-main-slot .s-card-container .s-product-image-container.s-image-overlay-grey {
  background: rgba(6,46,22,.62) !important;
}
html body #search .s-main-slot .s-card-container .s-product-image-container.s-image-overlay-grey::before,
html body #search .s-main-slot .s-card-container .s-product-image-container.s-image-overlay-grey::after {
  background: transparent !important;
}
html body #search .s-main-slot .s-card-container .s-background-color-platinum {
  background: var(--ahg-control) !important;
  color: var(--ahg-text) !important;
}

/* Desktop search toolbar: result count and sort controls share one surface. */
html body #a-page h1.s-desktop-toolbar {
  background: linear-gradient(145deg, rgba(13,92,47,.35), rgba(1,19,11,.59)) rgba(2,24,13,.43) !important;
  border-color: var(--ahg-edge) !important;
  box-shadow: inset 0 -1px 0 var(--ahg-edge) !important;
  color: var(--ahg-text) !important;
}
html body h1.s-desktop-toolbar > .s-desktop-width-max,
html body h1.s-desktop-toolbar .s-breadcrumb > .sg-col-inner,
html body h1.s-desktop-toolbar .s-desktop-sort-container > .sg-col-inner,
html body h1.s-desktop-toolbar .s-desktop-sort-container > .sg-col-inner > .a-section {
  background: transparent !important;
}
